CREATE TABLE IF NOT EXISTS notifications(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL,title VARCHAR(160) NOT NULL,message VARCHAR(1000) NOT NULL,is_read BOOLEAN NOT NULL DEFAULT FALSE,created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);CREATE INDEX IF NOT EXISTS idx_notifications_user ON notifications(user_id);
CREATE TABLE IF NOT EXISTS favorites(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL,course_id BIGINT NOT NULL,course_title VARCHAR(160) NOT NULL,course_description VARCHAR(2000) NOT NULL,course_category VARCHAR(100) NOT NULL,course_level VARCHAR(40) NOT NULL,course_price DECIMAL(12,2) NOT NULL,course_status VARCHAR(20) NOT NULL,course_start_date DATE,course_end_date DATE,course_image_url VARCHAR(500),created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT uk_favorites_user_course UNIQUE(user_id,course_id));
CREATE TABLE IF NOT EXISTS reviews(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,user_id BIGINT NOT NULL,user_name VARCHAR(160) NOT NULL,course_id BIGINT NOT NULL,rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 5),comment VARCHAR(1200) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT uk_reviews_user_course UNIQUE(user_id,course_id));CREATE INDEX IF NOT EXISTS idx_reviews_course ON reviews(course_id);
